/*
 * A040721  Continued fraction for sqrt(749).
 * https://oeis.org/A040721
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, easy
 * Formula:   continued fraction for sqrt(749), a(0) = floor(sqrt(749)),
 *            afterwards terms generated by: m_{k+1} = d_k*a_k - m_k d_{k+1} =
 *            (749 - m_{k+1}^2) / d_k a_{k+1} = floor( (27 + m_{k+1}) /
 *            d_{k+1} ) The period ends when a_{k+1} == 2*a(0)
 * Range:     u8 n <= 85, u16 n <= 85, u32 n <= 85, u64 n <= 85, u128 n <= 85,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* constant part of the continued fraction */
    const unsigned long long D = 749ULL;
    const unsigned long long a0 = 27ULL;   /* floor(sqrt(749)) */

    /* static storage for the period */
    static seq_t *period = NULL;
    static size_t period_len = 0;

    /* compute period on first use of a(n) with n > 0 */
    if (n > 0 && period_len == 0) {
        /* dynamic array building */
        size_t cap = 8;
        period = (seq_t *)malloc(cap * sizeof(seq_t));
        if (!period) return 0;          /* allocation failure */
        period_len = 0;

        unsigned long long m = 0;
        unsigned long long d = 1;
        unsigned long long a = a0;

        while (1) {
            /* next terms of the continued fraction */
            m = d * a - m;
            d = (D - m * m) / d;
            unsigned long long a_next = (a0 + m) / d;

            /* grow array if necessary */
            if (period_len >= cap) {
                cap *= 2;
                seq_t *tmp = (seq_t *)realloc(period, cap * sizeof(seq_t));
                if (!tmp) { free(period); return 0; }
                period = tmp;
            }
            period[period_len++] = (seq_t)a_next;

            if (a_next == 2 * a0)   /* period terminator */
                break;

            a = a_next;
        }
    }

    /* answer according to index */
    if (n == 0) {
        return (seq_t)a0;
    } else {
        /* period has already been computed */
        if (period_len == 0) {
            /* never happened: treat as empty */
            return 0;
        }
        /* periodic indexing: a(1) -> period[0] */
        idx_t idx = n - 1;
        idx_t pos = idx % (idx_t)period_len;
        return period[(size_t)pos];
    }
}
